        // Find the inorder predecessor
        Node *pred = (*curr)->left;

        while (pred->right != NULL && pred->right != *curr)
            pred = pred->right;

        // Create a temporary thread
        if (pred->right == NULL)
        {
            *data = (*curr)->data;
            *hasLeft = 1;
            *hasRight = ((*curr)->right != NULL);

            pred->right = *curr;
            *curr = (*curr)->left;

            return 1;
        }

        // Remove the temporary thread
        pred->right = NULL;
        *curr = (*curr)->right;
    }

    return 0;
}

